  {"qtype": "填空题", "difficulty": 2, "stem": "《论语·述而》中「三人行，______。______，其不善者而改之」，表明孔子虚心向他人学习的态度。", "options": [], "answer": "必有我师焉；择其善者而从之", "analysis": "本题考查《论语》名句默写。注意「焉」字不可写作「也」，「择」字不可写作「则」，两句顺序不可颠倒。易错点：把「必有我师焉」误作「必有我师也」。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "《诗经·卫风·氓》中「淇则有岸，______」两句，以水有岸泽有边反喻男子感情无定。", "options": [], "answer": "隰则有泮", "analysis": "考查《氓》中反比手法名句。「隰」指低湿之地，「泮」通「畔」，边岸之意。易错点：「隰」易误写为「湿」，「泮」易误写为「畔」（教材原文作「泮」）。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "屈原《离骚》中「______，虽九死其犹未悔」两句，表达诗人为追求美好理想而万死不辞的坚定信念。", "options": [], "answer": "亦余心之所善兮", "analysis": "考查《离骚》名句。「亦」字不可漏写，「善兮」的「兮」字不可丢。易错点：把「亦余心之所善兮」误作「亦余心之所好兮」。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "李白《蜀道难》中「扪参历井仰胁息，______」两句，摹写行人在高险山巅紧张屏息、以手抚胸的情态。", "options": [], "answer": "以手抚膺坐长叹", "analysis": "考查《蜀道难》名句。「膺」指胸口，不可写作「鹰」；「坐」意为「徒然、空」，不可写作「座」。易错点：「抚膺」误作「抚胸」。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "杜甫《登高》中「无边落木萧萧下，______」两句，被后人誉为「古今独步」，勾勒出夔州秋江壮阔之景。", "options": [], "answer": "不尽长江滚滚来", "analysis": "考查《登高》颔联。「萧萧」不可写作「箫箫」，「滚滚」不可写作「衮衮」。易错点：把「落木」误作「落叶」，教材原文为「落木」。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "白居易《琵琶行》中「千呼万唤始出来，______」两句，传神写出琵琶女迟疑羞涩的神态。", "options": [], "answer": "犹抱琵琶半遮面", "analysis": "考查《琵琶行》名句。「犹」意为「还、尚且」，不可写作「尤」；「遮」字注意走之底。易错点：把「始出来」误作「使出来」。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "苏轼《念奴娇·赤壁怀古》中「羽扇纶巾，谈笑间，______」三句，刻画周瑜从容破曹的儒将形象。", "options": [], "answer": "樯橹灰飞烟灭", "analysis": "考查《念奴娇》名句。「纶巾」的「纶」读 guān，不可写作「伦」；「樯橹」代指曹操水军，不可写作「墙撸」。易错点：部分版本作「强虏」，教材统编版从「樯橹」。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "辛弃疾《永遇乐·京口北固亭怀古》中「斜阳草树，寻常巷陌，______」三句，由眼前景引出对刘裕的怀念。", "options": [], "answer": "人道寄奴曾住", "analysis": "考查《永遇乐》名句。「寄奴」是刘裕的小字，不可写作「寄奴曾居」。易错点：把「人道」误作「人说」。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "荀子《劝学》中「君子博学而日参省乎己，______」两句，论述广泛学习与自我反省的重要意义。", "options": [], "answer": "则知明而行无过矣", "analysis": "考查《劝学》名句。「知」通「智」，但默写必须写作「知」，不可写作「智」；「矣」字不可丢。易错点：把「知明」误作「智明」。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "韩愈《师说》中「师者，______」一句，明确指出教师的根本职责。", "options": [], "answer": "所以传道受业解惑也", "analysis": "考查《师说》名句。「受」通「授」，教材原文作「受」，不可写作「授」。易错点：把「所以」误作「用来」，「受业」误作「授业」。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "杜牧《阿房宫赋》中「秦人不暇自哀，而后人哀之；______，______」四句，借秦亡历史警示当朝统治者。", "options": [], "answer": "后人哀之而不鉴之；亦使后人而复哀后人也", "analysis": "考查《阿房宫赋》主旨句。「鉴」意为「以……为鉴」，不可写作「见」；两句顺序不可颠倒。易错点：漏写「而」字，或把「复哀」误作「复悲」。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "苏轼《赤壁赋》中「寄蜉蝣于天地，______」两句，以比喻感叹人生短暂、个体渺小。", "options": [], "answer": "渺沧海之一粟", "analysis": "考查《赤壁赋》名句。「沧」不可写作「苍」，「粟」不可写作「栗」。易错点：把「沧海」误作「苍海」。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "庄子《逍遥游》中「水击三千里，______，去以六月息者也」三句，描写大鹏乘风高飞的壮观景象。", "options": [], "answer": "抟扶摇而上者九万里", "analysis": "考查《逍遥游》名句。「抟」意为「盘旋而上」，不可写作「团」；「扶摇」指旋风，不可写作「扶遥」。易错点：漏写「者」字。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "《诗经·卫风·氓》中「于嗟鸠兮，无食桑葚！______，______」四句，以鸠食桑葚起兴，劝诫女子不要沉溺于爱情。", "options": [], "answer": "于嗟女兮；无与士耽", "analysis": "考查《氓》中比兴句。「于」通「吁」，教材作「于」；「耽」意为「沉溺、迷恋」，不可写作「耽」的形近字「眈」。易错点：把「无与士耽」误作「无与士欢」。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "李商隐《锦瑟》中「庄生晓梦迷蝴蝶，______」两句，借用典故寄托诗人迷惘哀伤的情怀。", "options": [], "answer": "望帝春心托杜鹃", "analysis": "考查《锦瑟》名句。「望帝」即蜀帝杜宇，「杜鹃」又叫子规，不可写作「杜娟」。易错点：把「春心」误作「春情」。"},
